package com.shouxin.qa.review;
import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;import java.util.*;
/** Ensures every level-1 domain has a usable three-level default review flow. */
@Component public class ReviewFlowBootstrap implements ApplicationRunner {private final JdbcTemplate jdbc;public ReviewFlowBootstrap(JdbcTemplate j){jdbc=j;}
 public void run(ApplicationArguments a){List<Map<String,Object>> ds=jdbc.queryForList("SELECT id FROM qa_domain WHERE level_no=1 AND deleted=0");for(Map<String,Object>d:ds){String domain=String.valueOf(d.get("ID"));String flow="flow-"+domain;if(jdbc.queryForObject("SELECT COUNT(*) FROM qa_review_flow WHERE id=?",Integer.class,flow)==0){jdbc.update("INSERT INTO qa_review_flow(id,domain_l1_id,flow_version,pass_rule,enabled,created_by) VALUES(?,?,1,'ALL',1,'user-admin')",flow,domain);for(int l=1;l<=3;l++){String node=flow+"-l"+l;jdbc.update("INSERT INTO qa_review_flow_node(id,flow_id,level_no,node_name) VALUES(?,?,?,?)",node,flow,l,"第"+l+"级审核");jdbc.update("INSERT INTO qa_review_flow_reviewer(node_id,user_id) VALUES(?,?)",node,"user-admin");}}}}
}
